INSERT INTO member (first_name, last_name, email, web_page, short_cv, category, registration_number) VALUES
-- Μέλη ΔΕΠ 
('Γεώργιος', 'Παπαδόπουλος', 'gpapadopoulos@chaduni.gr', 'https://chaduni.gr/~gpapadopoulos', 'Καθηγητής στο τμήμα Πληροφορικής με ερευνητικά ενδιαφέροντα στην Τεχνητή Νοημοσύνη.\nΈχει δημοσιεύσει πληθώρα άρθρων σε διεθνή επιστημονικά περιοδικά και συνέδρια.\nΣυντονίζει ευρωπαϊκά ερευνητικά έργα και επιβλέπει διδακτορικές διατριβές.', 1, NULL),
('Ελένη', 'Οικονόμου', 'eoikonomou@chaduni.gr', 'https://chaduni.gr/~eoikonomou', 'Αναπληρώτρια Καθηγήτρια στον τομέα των Βάσεων Δεδομένων και Μεγάλων Δεδομένων.\nΗ έρευνά της εστιάζει στη βελτιστοποίηση ερωτημάτων και τα κατανεμημένα συστήματα.\nΔιδάσκει προπτυχιακά και μεταπτυχιακά μαθήματα διαχείρισης πληροφορίας.', 1, NULL),
('Δημήτριος', 'Κωνσταντίνου', 'dkonstantinou@chaduni.gr', 'https://chaduni.gr/~dkonstantinou', 'Επίκουρος Καθηγητής με εξειδίκευση στην Ασφάλεια Πληροφοριακών Συστημάτων.\nΑσχολείται με την κρυπτογραφία και την προστασία ιδιωτικότητας στα δίκτυα.\nΣυμμετέχει ενεργά σε επιτροπές αξιολόγησης διεθνών επιστημονικών εκδόσεων.', 1, NULL),

-- 2 researchers
('Μαρία', 'Βασιλείου', 'mvasileiou@chaduni.gr', 'https://chaduni.gr/~mvasileiou', 'Μεταδιδακτορική ερευνήτρια με εστίαση στη Μηχανική Μάθηση και την Όραση Υπολογιστών.\nΕργάζεται στην ανάπτυξη αλγορίθμων αναγνώρισης προτύπων σε ιατρικές εικόνες.\nΈχει λάβει υποτροφίες αριστείας για το ερευνητικό της έργο.', 2, NULL),
('Νικόλαος', 'Αντωνίου', 'nantoniou@chaduni.gr', 'https://chaduni.gr/~nantoniou', 'Κύριος ερευνητής στον τομέα του Υπολογιστικού Νέφους και του Διαδικτύου των Πραγμάτων.\nΣχεδιάζει αρχιτεκτονικές χαμηλής κατανάλωσης ενέργειας για έξυπνες πόλεις.\nΣυνεργάζεται με βιομηχανικούς εταίρους για την υλοποίηση πιλοτικών εφαρμογών.', 2, NULL),
('Αικατερίνη', 'Γεωργίου', 'ageorgiou@chaduni.gr', 'https://chaduni.gr/~ageorgiou', 'Ερευνήτρια στον τομέα της Επεξεργασίας Φυσικής Γλώσσας για την ελληνική γλώσσα.\nΑναπτύσσει γλωσσικά μοντέλα και εργαλεία ανάλυσης συναισθήματος.\nΈχει συμμετάσχει σε πολλά διεθνή ερευνητικά προγράμματα.', 2, NULL),

-- 3 phd candidates
('Κωνσταντίνος', 'Νικολάου', 'doc482910@chaduni.gr', 'https://chaduni.gr/~doc482910', 'Υποψήφιος διδάκτορας με θέμα διατριβής τα Βαθιά Νευρωνικά Δίκτυα.\nΕξετάζει μεθόδους μείωσης του υπολογιστικού κόστους κατά την εκπαίδευση μοντέλων.\nΒοηθά στα εργαστήρια των προπτυχιακών μαθημάτων προγραμματισμού.', 3, 'DOC482910'),
('Σοφία', 'Παπαδοπούλου', 'doc739104@chaduni.gr', 'https://chaduni.gr/~doc739104', 'Η διδακτορική της έρευνα αφορά την ανάλυση κοινωνικών δικτύων και γράφων.\nΜελετά αλγορίθμους εντοπισμού κοινοτήτων σε δυναμικά μεταβαλλόμενα δίκτυα.\nΈχει παρουσιάσει την εργασία της σε ευρωπαϊκά συνέδρια.', 3, 'DOC739104'),
('Αλέξανδρος', 'Μακρής', 'doc195832@chaduni.gr', 'https://chaduni.gr/~doc195832', 'Εκπονεί διδακτορική διατριβή στην Τεχνολογία Λογισμικού και τον αυτόματο έλεγχο κώδικα.\nΑναπτύσσει εργαλεία στατικής ανάλυσης για τον εντοπισμό σφαλμάτων ασφαλείας.\nΑποφοίτησε από το ίδιο τμήμα με άριστα.', 3, 'DOC195832'),
('Χριστίνα', 'Καραγιάννη', 'doc840261@chaduni.gr', 'https://chaduni.gr/~doc840261', 'Υποψήφια διδάκτορας στον τομέα της Αλληλεπίδρασης Ανθρώπου-Υπολογιστή.\nΣχεδιάζει προσβάσιμες διεπαφές χρήστη για άτομα με προβλήματα όρασης.\nΔιενεργεί πειράματα ευχρηστίας στο πλαίσιο του εργαστηρίου.', 3, 'DOC840261'),

-- 4: postgraduate student
('Παναγιώτης', 'Δημητρίου', 'ais739201@chaduni.gr', 'https://chaduni.gr/~ais739201', 'Μεταπτυχιακός φοιτητής στο πρόγραμμα Επιστήμης Δεδομένων.\nΕνδιαφέρεται για την προγνωστική ανάλυση και τη στατιστική μοντελοποίηση.\nΕκπονεί τη διπλωματική του εργασία πάνω σε δεδομένα υγείας.', 4, 'AIS739201'),
('Βασιλική', 'Αλεξίου', 'ais294815@chaduni.gr', 'https://chaduni.gr/~ais294815', 'Φοιτήτρια μεταπτυχιακού με κατεύθυνση στα Πληροφοριακά Συστήματα.\nΑσχολείται με τον σχεδιασμό βάσεων δεδομένων και την επιχειρηματική ευφυΐα.\nΣυμμετέχει στην ανάπτυξη εφαρμογών ιστού για το εργαστήριο.', 4, 'AIS294815'),
('Ιωάννης', 'Θεοδώρου', 'ais510394@chaduni.gr', 'https://chaduni.gr/~ais510394', 'Μεταπτυχιακός φοιτητής με ερευνητικά ενδιαφέροντα στην Κυβερνοασφάλεια.\nΜελετά επιθέσεις σε πρωτόκολλα ασύρματων δικτύων.\nΕργάζεται παράλληλα ως μηχανικός συστημάτων.', 4, 'AIS510394'),
('Αναστασία', 'Πετρίδου', 'ais864720@chaduni.gr', 'https://chaduni.gr/~ais864720', 'Φοιτήτρια του μεταπτυχιακού προγράμματος Τεχνητής Νοημοσύνης.\nΕστιάζει στην ενισχυτική μάθηση και τη ρομποτική.\nΑναπτύσσει προσομοιώσεις αυτόνομων πρακτόρων.', 4, 'AIS864720'),
('Χρήστος', 'Σταυρόπουλος', 'ais103948@chaduni.gr', NULL, 'Μεταπτυχιακός φοιτητής στον τομέα των Κατανεμημένων Συστημάτων.\nΑσχολείται με τεχνολογίες εικονικοποίησης και κοντέινερ.\nΗ διπλωματική του αφορά την εξισορρόπηση φορτίου στο νέφος.', 4, 'AIS103948'),
('Δήμητρα', 'Λαμπροπούλου', 'ais628491@chaduni.gr', NULL, 'Φοιτήτρια μεταπτυχιακού με ενδιαφέρον στην Ανάκτηση Πληροφορίας.\nΕξετάζει αλγορίθμους κατάταξης αποτελεσμάτων σε μηχανές αναζήτησης.\nΣυνεργάζεται με την ερευνητική ομάδα επεξεργασίας κειμένου.', 4, 'AIS628491'),

-- 5: undwergraduate students
('Ανδρέας', 'Μιχαηλίδης', 'ics194827@chaduni.gr', 'https://chaduni.gr/~ics194827', 'Τελειόφοιτος προπτυχιακός φοιτητής που εκπονεί πτυχιακή εργασία στο εργαστήριο.\nΑναπτύσσει εφαρμογή διαχείρισης ερευνητικών δημοσιεύσεων.\nΈχει ιδιαίτερο ενδιαφέρον για την ανάπτυξη λογισμικού ανοιχτού κώδικα.', 5, 'ICS194827'),
('Ευαγγελία', 'Σωτηρίου', 'ics382910@chaduni.gr', 'https://chaduni.gr/~ics382910', 'Προπτυχιακή φοιτήτρια του 4ου έτους με κατεύθυνση στην Επιστήμη Υπολογιστών.\nΣυμμετέχει εθελοντικά στη συντήρηση της ιστοσελίδας του εργαστηρίου.\nΕνδιαφέρεται για τη γραφιστική υπολογιστών και τα πολυμέσα.', 5, 'ICS382910'),
('Στέφανος', 'Αγγελίδης', 'ics592014@chaduni.gr', NULL, 'Φοιτητής 4ου έτους που ασχολείται με τον προγραμματισμό συστημάτων.\nΗ πτυχιακή του εργασία αφορά τη βελτιστοποίηση μεταγλωττιστών.\nΣυμμετέχει τακτικά σε διαγωνισμούς αλγορίθμων.', 5, 'ICS592014'),
('Ιωάννα', 'Κωστοπούλου', 'ics817263@chaduni.gr', NULL, 'Προπτυχιακή φοιτήτρια με ενδιαφέρον στις βάσεις δεδομένων.\nΒοηθά στην οργάνωση και καθαρισμό συνόλων δεδομένων για πειράματα.\nΣχεδιάζει να συνεχίσει σε μεταπτυχιακές σπουδές.', 5, 'ICS817263'),
('Μιχαήλ', 'Παναγιωτόπουλος', 'ics405918@chaduni.gr', NULL, 'Φοιτητής 3ου έτους με έφεση στα δίκτυα υπολογιστών.\nΣυμμετέχει στην ομάδα διαχείρισης της υποδομής του εργαστηρίου.\nΑσχολείται με λειτουργικά συστήματα Linux.', 5, 'ICS405918'),
('Αγγελική', 'Χατζηδάκη', 'ics928374@chaduni.gr', NULL, 'Τελειόφοιτη φοιτήτρια που εκπονεί πτυχιακή στη μηχανική μάθηση.\nΔοκιμάζει αλγορίθμους ταξινόμησης σε δεδομένα περιβαλλοντικών αισθητήρων.\nΑγαπά τον προγραμματισμό σε Python.', 5, 'ICS928374'),
('Θεόδωρος', 'Βλάχος', 'ics647382@chaduni.gr', NULL, 'Προπτυχιακός φοιτητής 4ου έτους στον τομέα της τεχνολογίας λογισμικού.\nΑναπτύσσει εργαλεία αυτοματοποίησης δοκιμών για εφαρμογές ιστού.\nΕργάζεται ομαδικά σε φοιτητικά πρότζεκτ.', 5, 'ICS647382'),
('Παρασκευή', 'Μαρκοπούλου', 'ics152637@chaduni.gr', NULL, 'Φοιτήτρια 3ου έτους με ενδιαφέρον στην ασφάλεια εφαρμογών.\nΜελετά κοινές ευπάθειες σε διαδικτυακές πλατφόρμες.\nΣυμμετέχει σε σεμινάρια κυβερνοασφάλειας.', 5, 'ICS152637'),
('Αθανάσιος', 'Ρήγας', 'ics738291@chaduni.gr', NULL, 'Τελειόφοιτος φοιτητής που ασχολείται με την ανάπτυξη κινητών εφαρμογών.\nΗ πτυχιακή του αφορά εφαρμογή πλοήγησης σε εσωτερικούς χώρους.\nΈχει εμπειρία σε περιβάλλοντα Android και iOS.', 5, 'ICS738291'),
('Όλγα', 'Διαμαντή', 'ics293847@chaduni.gr', NULL, 'Προπτυχιακή φοιτήτρια 4ου έτους με εστίαση στην ανάλυση δεδομένων.\nΧρησιμοποιεί εργαλεία οπτικοποίησης για την παρουσίαση στατιστικών στοιχείων.\nΣυνεργάζεται με μεταπτυχιακούς φοιτητές του εργαστηρίου.', 5, 'ICS293847'),
('Σπυρίδων', 'Καραμάνος', 'ics847362@chaduni.gr', NULL, 'Φοιτητής 3ου έτους που ενδιαφέρεται για την αρχιτεκτονική υπολογιστών.\nΜελετά τον παράλληλο προγραμματισμό σε κάρτες γραφικών.\nΣυμμετέχει ενεργά στις δραστηριότητες του εργαστηρίου.', 5, 'ICS847362'),
('Νίκη', 'Αποστόλου', 'ics516273@chaduni.gr', NULL, 'Τελειόφοιτη φοιτήτρια με κατεύθυνση στα πληροφοριακά συστήματα.\nΣχεδιάζει διεπαφές χρήστη για εσωτερικά εργαλεία του πανεπιστημίου.\nΕνδιαφέρεται για τη διαχείριση έργων πληροφορικής.', 5, 'ICS516273'),
('Εμμανουήλ', 'Σαμαράς', 'ics901827@chaduni.gr', NULL, 'Προπτυχιακός φοιτητής 4ου έτους με ενδιαφέρον στη ρομποτική.\nΠρογραμματίζει μικροελεγκτές για τη συλλογή δεδομένων από αισθητήρες.\nΣυμμετέχει σε φοιτητικές ομάδες τεχνολογίας.', 5, 'ICS901827'),
('Φωτεινή', 'Γαλάνη', 'ics364758@chaduni.gr', NULL, 'Φοιτήτρια 3ου έτους που ασχολείται με τη θεωρητική πληροφορική.\nΕνδιαφέρεται για τη θεωρία γράφων και τη συνδυαστική βελτιστοποίηση.\nΒοηθά στην προετοιμασία εκπαιδευτικού υλικού.', 5, 'ICS364758');
